// Route matrix MIRRORS WF01 Stage A (FAZA 2, 2026-07-17) — keep in sync
// manually (workflows sync to n8n by hand). BEG × 20 destinations +
// ZAG/SJJ/SKP/INI × 8 core destinations = 52 routes.
// Emits one item per (route × upcoming month): 52 × 3 = 156 TP calls, weekly.
const DESTS = ['IST','FCO','CDG','BCN','DXB','ATH','AMS','VIE','BUD','PRG','SKG','PMI','MLA','AYT','SPU','TIV','TLV','LHR','LIS','HKT'];
const CORE = ['IST','FCO','CDG','BCN','ATH','VIE','BUD','PRG'];
const ORIGIN_DESTS = { BEG: DESTS, ZAG: CORE, SJJ: CORE, SKP: CORE, INI: CORE };
const now = new Date();
const out = [];
for (const [origin, dests] of Object.entries(ORIGIN_DESTS)) {
  for (const dest of dests) {
    for (let m = 1; m <= 3; m++) {
      const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + m, 1));
      out.push({ json: { origin, dest, month: d.toISOString().slice(0, 7) } });
    }
  }
}
return out;

// Aggregate TP fares per route across the 3 sampled months, take the
// median. TP returns cheapest-per-date fares; the median of ~90 daily
// cheapest fares is the 'typical bookable price' WF01's deal gate
// (flight <= 70% of medianFlightPrice) compares against.
// Items flow 1:1 through the HTTP node, so index i matches request i.
const reqs = $('Routes × months').all();
const resps = $input.all();
const byRoute = {};
for (let i = 0; i < reqs.length; i++) {
  const { origin, dest } = reqs[i].json;
  const fares = (resps[i]?.json?.data || [])
    .map(f => Number(f.value ?? f.price))
    .filter(v => Number.isFinite(v) && v > 0);
  const key = `${origin}_${dest}`;
  (byRoute[key] ||= { origin, dest, values: [] }).values.push(...fares);
}
const out = [];
for (const key of Object.keys(byRoute)) {
  const { origin, dest, values } = byRoute[key];
  if (values.length < 10) continue; // sample too thin to trust
  values.sort((a, b) => a - b);
  const median = Math.round(values[Math.floor(values.length / 2)]);
  out.push({ json: { key, origin, dest, medianFlightPrice: median, sampleSize: values.length } });
}
return out;
